@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Gowun+Batang:wght@400;700&family=IBM+Plex+Sans+KR:wght@400;500;600;700&display=swap');
:root{--bg:#101114;--panel:#17181b;--panel2:#1d1e22;--line:#34353a;--muted:#85858a;--text:#e9e6df;--amber:#d8aa6a;--red:#c66c64;--green:#88a58e;--blue:#88aab9;--purple:#a896bd;--mono:'DM Mono',monospace;--sans:'IBM Plex Sans KR',sans-serif;--serif:'Gowun Batang',serif}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:var(--sans);min-height:100vh}.noise{position:fixed;inset:0;pointer-events:none;z-index:9;opacity:.035;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.5'/%3E%3C/svg%3E")}
#app{max-width:1180px;margin:auto;padding:0 36px}.topbar{height:68px;border-bottom:1px solid #2a2b2e;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:12px}.brand-mark{width:31px;height:31px;border:1px solid #817153;display:grid;place-items:center;color:var(--amber);font-size:20px}.brand-name{font:500 13px var(--mono);letter-spacing:2px}.brand-name span{color:var(--amber)}.brand-sub{font-size:10px;color:#777;margin-top:3px;letter-spacing:.3px}.route{font:11px var(--mono);color:#909094;display:flex;align-items:center;gap:10px}.route b{color:#d7d2c8;font-weight:400}.route i{color:#4d4d50;font-style:normal}.live-dot{height:6px;width:6px;background:#a65e55;border-radius:50%;box-shadow:0 0 9px #bd655b}.icon-btn{border:1px solid #38393c;color:#b1a184;background:none;height:31px;width:34px;cursor:pointer;font-size:16px}.icon-btn:hover{border-color:var(--amber)}
.mission-head{height:108px;display:flex;justify-content:space-between;align-items:center}.eyebrow{font:10px var(--mono);letter-spacing:1.55px;color:#a28b67}.mission-head h1{font:700 27px var(--serif);margin:7px 0 3px;letter-spacing:-.7px}.mission-head h1 em{color:var(--amber);font-style:normal}.mission-head p{margin:0;color:#87858a;font-size:11px}.phase{display:flex;align-items:center;gap:12px;border-left:1px solid #3b3a38;padding-left:17px;font-size:10px;color:#838187;line-height:1.7}.phase-no{font:22px var(--mono);color:var(--amber)}.phase b{color:#d4d0c8;font-size:11px;font-weight:500}
.battlefield{height:350px;position:relative;overflow:hidden;border:1px solid #343438;background:linear-gradient(180deg,#202124 0%,#191a1d 56%,#252427 100%);isolation:isolate}.battlefield:before{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(8,9,11,.48),transparent 30%,transparent 72%,rgba(9,10,12,.37)),radial-gradient(ellipse at 68% 48%,rgba(116,88,77,.18),transparent 42%);z-index:-1}.scene-grid{position:absolute;inset:0;opacity:.24;background:linear-gradient(90deg,transparent 0 13%,#646163 13.1%,transparent 13.3% 28%,#4c4a4b 28.1%,transparent 28.3% 46%,#454346 46.1%,transparent 46.3% 65%,#555153 65.1%,transparent 65.3% 83%,#4c494b 83.1%,transparent 83.3%),linear-gradient(0deg,transparent 0 25%,#575457 25.2%,transparent 25.7% 76%,#555255 76.2%,transparent 76.5%)}.station-sign{position:absolute;left:34px;top:31px;color:#a6a0a0;font:10px var(--mono);letter-spacing:1.7px;border-top:1px solid #8e7560;padding-top:7px;width:132px}.station-sign strong{font-size:19px;color:#d4b28b;margin-left:4px}.station-sign small{display:block;color:#777579;margin-top:4px;font:9px var(--sans);letter-spacing:.3px}.weather{position:absolute;top:32px;right:35px;font-size:10px;color:#858185}.weather span{color:#ac806d;margin-left:9px;letter-spacing:3px}.rail{position:absolute;height:1px;left:0;right:0;background:#827c77;opacity:.31;transform:perspective(220px) rotateX(18deg)}.rail-back{bottom:59px}.rail-front{bottom:34px;height:2px;opacity:.46}.rail:after{content:"";position:absolute;inset:-1px 0;background:repeating-linear-gradient(90deg,transparent 0 24px,#8a817b 25px 27px,transparent 28px 51px);opacity:.5}.enemy-wrap{position:absolute;left:51%;top:12px;bottom:0;width:46%;transform:translateX(-1%)}.enemy-label{position:absolute;top:18px;left:50%;transform:translateX(-50%);white-space:nowrap;text-align:center;z-index:2}.tag{font:9px var(--mono);padding:3px 6px;letter-spacing:.5px}.danger{color:#dfa093;border:1px solid #83534d;background:#452c2b}.enemy-name{display:block;font:700 18px var(--serif);margin-top:7px;text-shadow:0 2px 6px #000}.enemy-sub{font-size:10px;color:#aba1a0;display:block;margin-top:2px}.enemy-figure{position:absolute;left:50%;bottom:41px;width:180px;height:220px;transform:translateX(-50%);filter:drop-shadow(0 11px 15px #0009);transition:transform .35s,filter .3s}.halo{position:absolute;width:153px;height:153px;left:12px;top:17px;border-radius:50%;border:1px solid #aa9281;opacity:.11;box-shadow:0 0 0 14px #b19d8810,0 0 38px #cfb8a022}.coat{position:absolute;left:42px;top:93px;width:100px;height:117px;background:linear-gradient(90deg,#272729 0%,#504747 42%,#352f31 65%,#1d1d20 100%);clip-path:polygon(25% 0,74% 0,94% 30%,100% 100%,0 100%,8% 30%);border-top:2px solid #978574}.coat:after{content:"";position:absolute;left:48px;top:5px;width:1px;height:105px;background:#a28d7a;opacity:.48}.neck{position:absolute;left:78px;top:73px;width:25px;height:29px;background:#b8a89b}.head{position:absolute;left:61px;top:30px;width:61px;height:68px;background:linear-gradient(135deg,#d4c7b5,#817b76);border-radius:48% 49% 43% 46%;transform:rotate(-5deg);box-shadow:inset -13px -2px 17px #343237}.head:after{content:"";position:absolute;width:19px;height:26px;left:-9px;top:20px;background:#cbc0b2;border-radius:50%}.eye{position:absolute;top:30px;width:8px;height:3px;background:#d67c70;box-shadow:0 0 9px #f18472}.eye-a{left:12px}.eye-b{right:12px}.crack{position:absolute;top:6px;left:31px;width:2px;height:57px;background:#39383b;transform:rotate(15deg);clip-path:polygon(0 0,100% 0,40% 40%,100% 48%,20% 76%,60% 100%,0 100%,40% 77%,0 51%,60% 41%)}.arm{position:absolute;top:101px;width:27px;height:94px;background:linear-gradient(90deg,#3b3334,#82756b,#302c30);transform-origin:top;border-radius:14px}.arm-a{left:42px;transform:rotate(25deg)}.arm-b{right:38px;transform:rotate(-34deg)}.legs{position:absolute;bottom:2px;left:67px;width:50px;height:51px;background:linear-gradient(90deg,#29282b 0 44%,transparent 46% 52%,#28272a 54%);clip-path:polygon(4% 0,96% 0,86% 100%,53% 100%,48% 27%,41% 100%,5% 100%)}.glass-shard{position:absolute;width:19px;height:38px;background:linear-gradient(150deg,#c7e0dc66,#e5bba066 45%,transparent);clip-path:polygon(49% 0,100% 39%,60% 100%,0 57%);filter:drop-shadow(0 0 5px #b9d1c955);animation:float 3s ease-in-out infinite}.s1{left:12px;top:96px}.s2{right:6px;top:88px;transform:rotate(32deg);animation-delay:-.8s}.s3{right:20px;top:148px;transform:scale(.7) rotate(-23deg);animation-delay:-1.4s}@keyframes float{50%{translate:0 -8px;rotate:8deg}}.enemy-figure.hit{transform:translateX(-50%) translateX(18px);filter:drop-shadow(0 0 17px #d5796e)}.enemy-figure.down{filter:grayscale(.8) brightness(.6);transform:translateX(-50%) rotate(9deg)}
.enemy-hud{position:absolute;right:19px;bottom:17px;width:186px;background:#111214dd;border:1px solid #484346;padding:9px 11px 8px;z-index:2}.hud-row{display:flex;justify-content:space-between;color:#a19da0;font-size:9px;margin-bottom:5px}.hud-row b{font:10px var(--mono);color:#e0d9d4}.bar{height:4px;background:#3a3435;margin-bottom:8px}.bar i{display:block;height:100%;transition:width .4s}.bar.hp i{background:linear-gradient(90deg,#954c4b,#d17669)}.bar.stagger i{background:#d7b169;width:0}.hud-row.secondary{font-size:8px;color:#7f7b7c;margin-bottom:4px}.hud-row.secondary b{font-size:9px}.status-list{display:flex;gap:4px}.status-chip{font:8px var(--mono);padding:2px 4px;color:#e3b875;border:1px solid #725c3d}.intent-card{position:absolute;left:26px;bottom:17px;width:192px;border:1px solid #5b4441;background:#171517e8;padding:9px 11px}.intent-title{display:flex;justify-content:space-between;color:#c47e70;font-size:9px}.intent-title b{font:8px var(--mono);color:#777}.intent-main{display:flex;gap:9px;align-items:center;margin-top:8px}.intent-die{color:#d07c6d;font-size:23px}.intent-main strong{font-size:10px;display:block;font-weight:600}.intent-main small{display:block;color:#979094;font-size:8px;margin-top:3px}.combat-log{position:absolute;left:50%;transform:translateX(-50%);bottom:8px;color:#bbb5af;font-size:9px;white-space:nowrap;text-shadow:0 1px 3px black;display:flex;gap:7px;align-items:center}.log-mark{color:var(--amber);font:13px var(--mono)}
.lower{display:grid;grid-template-columns:290px 1fr;gap:13px;margin-top:13px}.team-panel,.orders-panel{border:1px solid #323337;background:#17181b}.team-panel{padding:13px 13px 11px}.panel-title{font:11px var(--mono);letter-spacing:.6px;color:#d5d0c8;display:flex;align-items:center;gap:9px}.small-muted{font:8px var(--mono);letter-spacing:.3px;color:#747378}.team-list{display:grid;gap:5px;margin-top:10px}.unit-card{height:46px;border:1px solid #35363a;background:#1c1d20;display:flex;align-items:center;padding:5px 8px;gap:9px;cursor:pointer;transition:.18s;position:relative}.unit-card:hover{border-color:#77705f}.unit-card.selected{border-color:#b89a6d;background:#26231f;box-shadow:inset 2px 0 #c5a16d}.unit-card.dead{opacity:.42;filter:grayscale(1)}.unit-avatar{height:32px;width:31px;border:1px solid #55504a;background:linear-gradient(145deg,#383438,#191a1d);display:grid;place-items:center;font:17px var(--serif);color:var(--amber)}.unit-info{flex:1;min-width:0}.unit-name{font-size:10px;font-weight:600;display:flex;justify-content:space-between}.unit-role{font-size:8px;color:#89878b;margin-top:1px}.mini-hp{height:3px;background:#393638;margin-top:4px}.mini-hp i{display:block;height:100%;background:#a95c54}.unit-extra{font:9px var(--mono);color:#aaa2a0;text-align:right}.unit-extra small{display:block;font-size:7px;color:#79767a;margin-top:3px}.unit-card.ordered:after{content:'✓';position:absolute;right:7px;top:3px;color:#9eb39a;font-size:12px}.sin-bar{border-top:1px solid #333438;margin-top:10px;padding-top:8px}.sin-title{font-size:9px;color:#c7c1b6}.sin-title span{font:12px var(--mono);color:var(--amber);margin-left:7px}.sin-title small{color:#68676b}.sin-pips{display:flex;gap:4px;margin:6px 0}.sin-pip{height:5px;flex:1;background:#343438}.sin-pip.on{background:#c9a56d;box-shadow:0 0 5px #bc98614b}.sin-caption{font-size:8px;color:#77767a}.sin-caption b{color:#cbb183;font-weight:500}
.orders-panel{padding:13px 14px 10px;min-width:0}.orders-top{display:flex;justify-content:space-between;align-items:center}.order-count{font:9px var(--mono);color:#a99069;border:1px solid #554b3b;padding:2px 5px}.helper{font-size:9px;color:#818085;margin-top:5px}.resolve-btn{background:#9e7447;border:1px solid #c39a68;color:#171514;height:38px;padding:0 13px;display:flex;gap:17px;align-items:center;font:600 10px var(--sans);cursor:pointer;transition:.2s}.resolve-btn:hover:not(:disabled){background:#c19561;transform:translateY(-1px)}.resolve-btn:disabled{background:#393531;color:#77716a;border-color:#51483b;cursor:not-allowed}.resolve-btn b{font:12px var(--mono)}.skill-row{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:12px}.skill-card{position:relative;min-height:94px;padding:8px;border:1px solid #3c3b3c;background:#202023;cursor:pointer;text-align:left;color:var(--text);transition:.18s;overflow:hidden}.skill-card:hover:not(.locked){transform:translateY(-2px);border-color:#8c785a}.skill-card.chosen{border-color:#d0aa70;background:#29251f;box-shadow:inset 0 0 0 1px #8f724b}.skill-card.locked{opacity:.38;cursor:not-allowed}.skill-top{display:flex;justify-content:space-between;align-items:center}.skill-name{font-size:11px;font-weight:600}.skill-cost{font:8px var(--mono);color:#a68d65}.skill-desc{font-size:8px;color:#969298;margin-top:5px;line-height:1.5}.skill-dice{display:flex;gap:4px;margin-top:7px;align-items:center}.coin{height:16px;min-width:16px;padding:0 4px;display:grid;place-items:center;border:1px solid #68605a;color:#c1b59d;font:8px var(--mono);background:#29272a}.coin.attack{border-color:#8a6054;color:#df9a78}.coin.defense{border-color:#617b79;color:#9dc0b2}.coin.final{margin-left:auto;border:0;background:none;color:#b8a077;font:8px var(--mono)}.target-row{min-height:18px;margin-top:8px;display:flex;align-items:center;justify-content:space-between;color:#827f83;font-size:8px}.target-choices{display:flex;gap:5px}.target-btn{border:1px solid #454448;background:#202023;color:#bcb7b0;font:8px var(--mono);padding:3px 7px;cursor:pointer}.target-btn.active{border-color:#ad8060;color:#e3bb84;background:#302822}.target-btn:disabled{opacity:.4;cursor:default}
footer{height:38px;display:flex;align-items:center;justify-content:space-between;color:#67666a;font:8px var(--mono);letter-spacing:.5px}footer b{color:#a48d69;font-weight:400}#footerState{color:#87827a}.modal{position:fixed;inset:0;background:#090a0bd9;z-index:20;display:grid;place-items:center;padding:20px}.modal.hidden{display:none}.modal-card{width:min(420px,100%);border:1px solid #615343;background:#19191b;text-align:center;padding:38px 28px;box-shadow:0 20px 70px #0009}.result-icon{font-size:31px;color:var(--amber);margin-bottom:13px}.modal-card h2{font:700 24px var(--serif);margin:12px 0}.modal-card p{color:#a09b99;font-size:12px;line-height:1.8}.modal-card button{background:#9e7447;border:0;color:#171514;padding:11px 20px;font:600 11px var(--sans);margin-top:13px;cursor:pointer}.modal-card button span{margin-left:12px}.toast{position:fixed;top:80px;left:50%;transform:translate(-50%,-10px);background:#262321;border:1px solid #8e7250;padding:9px 15px;color:#e1c18f;font-size:10px;opacity:0;transition:.25s;pointer-events:none;z-index:30}.toast.show{opacity:1;transform:translate(-50%,0)}.shake{animation:shake .3s}@keyframes shake{25%{transform:translateX(-7px)}70%{transform:translateX(6px)}}.flash{animation:flash .4s}@keyframes flash{50%{background:#673d39}}
@media(max-width:800px){#app{padding:0 17px}.battlefield{height:335px}.enemy-wrap{left:43%;width:55%}.enemy-hud{right:10px;width:165px}.intent-card{left:10px;width:170px}.lower{grid-template-columns:245px 1fr}.team-panel{padding:11px 9px}.orders-panel{padding:11px 10px}.skill-card{padding:7px;min-height:100px}.route{gap:6px;font-size:9px}}
@media(max-width:620px){#app{padding:0 12px}.topbar{height:57px}.brand-sub{font-size:8px}.route{font-size:8px;gap:4px}.route i,.route b:first-of-type{display:none}.mission-head{height:96px}.mission-head h1{font-size:22px}.mission-head p{font-size:9px}.phase{padding-left:10px;gap:7px}.phase-no{font-size:18px}.battlefield{height:328px}.station-sign{left:14px;top:16px}.weather{right:13px;top:18px;font-size:8px}.enemy-wrap{left:36%;width:64%;top:0}.enemy-label{top:48px}.enemy-name{font-size:15px}.enemy-sub{font-size:8px}.enemy-figure{transform:translateX(-50%) scale(.82);transform-origin:bottom center;bottom:35px}.enemy-hud{right:8px;bottom:12px;width:145px;padding:7px}.intent-card{left:8px;bottom:12px;width:148px;padding:7px}.intent-main strong{font-size:9px}.combat-log{font-size:8px;bottom:3px;max-width:95%;overflow:hidden}.lower{grid-template-columns:1fr;gap:8px;margin-top:8px}.team-panel{padding:9px}.team-list{grid-template-columns:repeat(3,1fr);gap:4px;margin-top:7px}.unit-card{height:53px;padding:4px;gap:5px;align-items:flex-start}.unit-avatar{height:27px;width:25px;flex:none}.unit-info{padding-top:1px}.unit-name{font-size:8px;display:block;white-space:nowrap}.unit-role{font-size:7px;white-space:nowrap}.mini-hp{margin-top:4px}.unit-extra{display:none}.sin-bar{margin-top:7px;padding-top:6px}.sin-title,.sin-caption{font-size:8px}.orders-panel{padding:10px}.skill-row{gap:5px;margin-top:9px}.skill-card{min-height:88px;padding:6px}.skill-name{font-size:9px}.skill-desc{font-size:7px}.skill-cost{font-size:7px}.skill-dice{gap:2px;margin-top:5px}.coin{min-width:14px;height:14px;font-size:7px}.resolve-btn{height:33px;padding:0 9px;gap:8px;font-size:9px}.helper{font-size:8px}.target-row{font-size:7px}footer{height:32px;font-size:7px}}

const units=[
 {id:'mira',name:'서미라',role:'전직 역무원',mark:'月',color:'#b8a283',hp:92,max:92,san:10,maxSan:25,speed:[3,6],skills:[
  {name:'표 검표',sin:'분노',symbol:'R',color:'#c97868',base:4,coin:4,n:1,desc:'기본 공격 · 적중 시 정신력 +2',effect:'calm'},
  {name:'막차 안내',sin:'우울',symbol:'S',color:'#7d9bac',base:3,coin:5,n:2,desc:'2연격 · 앞면마다 +5 위력',effect:'double'},
  {name:'개찰구 폐쇄',sin:'오만',symbol:'P',color:'#c2a15d',base:6,coin:7,n:2,cost:3,desc:'강한 2연격 · 흐트러짐 피해 +8',effect:'heavy'}]},
 {id:'dojin',name:'강도진',role:'야간 경비',mark:'刃',color:'#93a9a0',hp:108,max:108,san:2,maxSan:25,speed:[2,5],skills:[
  {name:'손전등 후려치기',sin:'탐식',symbol:'G',color:'#a88168',base:5,coin:3,n:1,desc:'적중 시 다음 공격 위력 -1',effect:'weaken'},
  {name:'안전선 돌파',sin:'분노',symbol:'R',color:'#c97868',base:2,coin:6,n:2,desc:'2연격 · 앞면마다 +6 위력',effect:'double'},
  {name:'비상 제동',sin:'나태',symbol:'L',color:'#b0a96e',base:6,coin:5,n:3,cost:3,desc:'3연격 · 마지막 타격 강화',effect:'brake'}]},
 {id:'yun',name:'윤해진',role:'분실물 담당',mark:'⌁',color:'#a69abb',hp:78,max:78,san:18,maxSan:25,speed:[4,7],skills:[
  {name:'유리 조각',sin:'질투',symbol:'E',color:'#aa86ad',base:3,coin:4,n:2,desc:'2연격 · 앞면마다 +4 위력',effect:'double'},
  {name:'승객 명부',sin:'우울',symbol:'S',color:'#7d9bac',base:5,coin:4,n:1,desc:'정신력 낮은 적에게 큰 피해',effect:'focus'},
  {name:'이름을 불러',sin:'오만',symbol:'P',color:'#c2a15d',base:4,coin:6,n:3,cost:3,desc:'3연격 · 정신력 +4',effect:'call'}]}
];
const enemy={hp:180,max:180,stagger:0,maxStagger:60,weak:false};
let turn=1,selected=0,orders={},sin=[],busy=false,gameOver=false,enemyPowerDown=0;
const $=s=>document.querySelector(s), teamList=$('#teamList'),skillRow=$('#skillRow'),targetRow=$('#targetRow');
const sinColors={분노:'#c97868',우울:'#7d9bac',오만:'#c2a15d',탐식:'#a88168',나태:'#b0a96e',질투:'#aa86ad'};
function roll(a,b){return Math.floor(Math.random()*(b-a+1))+a}function clamp(x,a,b){return Math.max(a,Math.min(b,x))}
function alive(){return units.filter(u=>u.hp>0)}
function log(text){$('#combatLog').innerHTML=`<span class="log-mark">!</span><span>${text}</span>`}
function toast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1900)}
function render(){
 teamList.innerHTML=units.map((u,i)=>`<div class="unit-card ${i===selected?'selected':''} ${u.hp<=0?'dead':''} ${orders[u.id]?'ordered':''}" data-unit="${i}"><div class="unit-avatar" style="color:${u.color}">${u.mark}</div><div class="unit-info"><div class="unit-name">${u.name}<span style="color:#aaa;font:8px var(--mono)">${u.hp>0?u.hp+' HP':'전투 불능'}</span></div><div class="unit-role">${u.role} · 정신력 ${u.san>=0?'+':''}${u.san}</div><div class="mini-hp"><i style="width:${u.hp/u.max*100}%;background:${u.hp/u.max<.3?'#d27868':''}"></i></div></div><div class="unit-extra">${u.hp>0?`${u.speed[0]}–${u.speed[1]}<small>SPEED</small>`:'—'}</div></div>`).join('');
 teamList.querySelectorAll('.unit-card').forEach(el=>el.onclick=()=>{if(busy)return;selected=+el.dataset.unit;if(units[selected].hp<=0){toast('전투 불능인 인원은 명령할 수 없습니다.');return}render()});
 const u=units[selected];
 if(!u||u.hp<=0){skillRow.innerHTML='<div class="helper">전투 가능한 인원을 선택하세요.</div>';targetRow.innerHTML='';return}
