  }
 }
 await wait(350);$('#enemyFigure').classList.remove('flash','hit');enemyPowerDown=Math.max(0,enemyPowerDown-1);turn++;orders={};busy=false;selected=alive().length?units.indexOf(alive()[0]):0;render();
